		s[count] = (byte)(this.ok ? 1 : 0);
		count += sizeof(bool);
		
		// serverVersion 쓰기 (LittleEndian 명시 — wire format 약속)
		success &= BinaryPrimitives.TryWriteUInt16LittleEndian(s.Slice(count, s.Length - count), this.serverVersion);
		count += sizeof(ushort);
		
		// reason 문자열 쓰기 (Length prefix UInt16 LittleEndian + UTF-16 payload)
		ushort reasonLen = (ushort)Encoding.Unicode.GetByteCount(this.reason);
		success &= BinaryPrimitives.TryWriteUInt16LittleEndian(s.Slice(count, s.Length - count), reasonLen);
		count += sizeof(ushort);
		Encoding.Unicode.GetBytes(this.reason.AsSpan(), s.Slice(count, s.Length - count));
		count += reasonLen;
		

        // 최종 size 기록
        success &= BinaryPrimitives.TryWriteUInt16LittleEndian(s, count);

        if (!success)
            return default;

        return new ArraySegment<byte>(segment, 0, count);
    }
}

